import React, { useState } from "react";
import Home from "./pages/Home";
import AdminLogin from "./pages/AdminLogin";
import AdminPanel from "./pages/AdminPanel";
import UserLogin from "./pages/UserLogin";

function App() {
  const [view, setView] = useState("home");
  const [adminToken, setAdminToken] = useState("");
  const [userToken, setUserToken] = useState("");

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h1>Traffic Challan System</h1>

      <div style={{ marginBottom: 20 }}>
        <button onClick={() => setView("home")}>Home</button>
        <button onClick={() => setView("adminLogin")}>Admin Login</button>
        <button
          onClick={() => {
            if (adminToken) setView("adminPanel");
            else alert("Please login as Admin first");
          }}
        >
          Admin Panel
        </button>
        <button onClick={() => setView("userLogin")}>User Login</button>
      </div>

      {view === "home" && <Home />}
      {view === "adminLogin" && (
        <AdminLogin setAdminToken={setAdminToken} setView={setView} />
      )}
      {view === "adminPanel" && <AdminPanel adminToken={adminToken} />}
      {view === "userLogin" && <UserLogin setUserToken={setUserToken} />}
    </div>
  );
}

export default App;
